def find_last_started_test_from_stdout(stdout_lines: list[str], batch):
    # Identify the last test that a progress bar reported as started but never
    # reported as completed ("... took Ns"). Used to blame a crashing test.
    started_tests = []
    completed_tests = set()
    for line in stdout_lines:
        progress_match = PROGRESS_TEST_START_PATTERN.match(line.strip())
        if not progress_match:
            continue
        progress_text = progress_match.group(1)
        if " took " in progress_text:
            completed_tests.add(progress_text.split(" took ", 1)[0])
        else:
            started_tests.append(progress_text)
    for test_name in reversed(started_tests):
        if test_name not in completed_tests:
            return test_name
    if started_tests:
        return started_tests[-1]
    if batch:
        return batch[0] if len(batch) == 1 else batch[-1]
    return None


def extract_sanitizer_block(stderr_lines: list[str]):
    start_idx = None
    for idx, line in enumerate(stderr_lines):
        if SANITIZER_ERROR_PATTERN.match(line):
            start_idx = idx
            break
    if start_idx is None:
        return []
