        if line.startswith("~~~~"):
            break
        if line.strip() == SKIPPED_SUMMARY_HEADER:
            break
        block.append(line.rstrip())
    while block and not block[-1].strip():
        block.pop()
    return block


def extract_result_sections(stderr_lines: list[str]):
    # Capture the verbatim "Expected result:" / "Actual result:" labeled
    # sections (dropping the decorative "====" separators) so the reader can
    # see the diff that produced the failure.
