            continue
        block = [stdout_lines[idx].rstrip()]
        has_expansion = False
        for lookahead in stdout_lines[idx + 1 :]:
            stripped = lookahead.strip()
            if lookahead.startswith("~~~~") or stripped == SKIPPED_SUMMARY_HEADER:
                break
            if PROGRESS_TEST_START_PATTERN.match(stripped):
                break
            if FAILED_HEADER_PATTERN.match(lookahead):
                break
            block.append(lookahead.rstrip())
            if EXPANSION_PATTERN.match(lookahead):
                has_expansion = True
        while block and not block[-1].strip():
            block.pop()
        if has_expansion:
            return block
    return None


